import java.util.*;

public class Main {
    static double[] medianSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        double[] result = new double[n - k + 1];
        for (int i = 0; i + k <= n; i++) {
            int[] window = Arrays.copyOfRange(nums, i, i + k);
            Arrays.sort(window);
            int mid = k / 2;
            if (k % 2 == 1) {
                result[i] = window[mid];
            } else {
                result[i] = ((long) window[mid - 1] + window[mid]) / 2.0;
            }
        }
        return result;
    }

