import java.util.*;

public class Main {
    static double[] medianSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        List<Integer> window = new ArrayList<>();
        for (int i = 0; i < k; i++) insertSorted(window, nums[i]);

        double[] result = new double[n - k + 1];
        result[0] = median(window, k);

        for (int i = k; i < n; i++) {
            insertSorted(window, nums[i]);
            removeSorted(window, nums[i - k]);
            result[i - k + 1] = median(window, k);
        }
        return result;
    }

    static void insertSorted(List<Integer> window, int val) {
        int pos = Collections.binarySearch(window, val);
        if (pos < 0) pos = -(pos + 1);
        window.add(pos, val);
    }

    static void removeSorted(List<Integer> window, int val) {
        int pos = Collections.binarySearch(window, val);
        window.remove(pos);
    }

    static double median(List<Integer> window, int k) {
        int mid = k / 2;
        if (k % 2 == 1) return window.get(mid);
        return ((long) window.get(mid - 1) + window.get(mid)) / 2.0;
    }

    public static void main(String[] args) {
        System.out.println(Arrays.toString(medianSlidingWindow(new int[]{1, 3, -1, -3, 5, 3, 6, 7}, 3)));
        System.out.println(Arrays.toString(medianSlidingWindow(new int[]{1, 2, 3, 4, 2, 3, 1, 4, 2}, 3)));
    }
}

